from typing import List

class Solution:
    def canCross(self, stones: List[int]) -> bool:
        stone_set = set(stones)
        dp = {s: set() for s in stones}
        dp[0].add(0)

        for s in stones:
            for jump in dp[s]:
                for step in (jump - 1, jump, jump + 1):
                    if step > 0 and (s + step) in stone_set:
                        dp[s + step].add(step)

        return len(dp[stones[-1]]) > 0

class Solution {
public:
    bool canCross(vector<int>& stones) {
        unordered_map<int, unordered_set<int>> dp;
        for (int s : stones) dp[s] = unordered_set<int>();
        dp[0].insert(0);

        for (int s : stones) {
            for (int jump : dp[s]) {
                for (int step = jump - 1; step <= jump + 1; step++) {
                    if (step > 0 && dp.count(s + step)) {
                        dp[s + step].insert(step);
                    }
                }
            }
        }
        return !dp[stones.back()].empty();
    }
};

class Solution {
    public boolean canCross(int[] stones) {
        Map<Integer, Set<Integer>> dp = new HashMap<>();
        for (int s : stones) {
            dp.put(s, new HashSet<>());
        }
        dp.get(0).add(0);

        for (int s : stones) {
            for (int jump : dp.get(s)) {
                for (int step = jump - 1; step <= jump + 1; step++) {
                    if (step > 0 && dp.containsKey(s + step)) {
                        dp.get(s + step).add(step);
                    }
                }
            }
        }
        return !dp.get(stones[stones.length - 1]).isEmpty();
    }
}

var canCross = function(stones) {
    const dp = new Map();
    for (const s of stones) {
        dp.set(s, new Set());
    }
    dp.get(0).add(0);

    for (const s of stones) {
        const jumps = dp.get(s);
        for (const jump of jumps) {
            for (let step = jump - 1; step <= jump + 1; step++) {
                if (step > 0 && dp.has(s + step)) {
                    dp.get(s + step).add(step);
                }
            }
        }
    }
    return dp.get(stones[stones.length - 1]).size > 0;
};
